      return;
    }

  if (msr_candidates > 99 && inference_ms > 9999)
    {
      snprintf(model_text, sizeof(model_text), "M:99+ AI:9999+");
    }
  else if (msr_candidates > 99)
    {
      snprintf(model_text, sizeof(model_text), "M:99+ AI:%lu",
