          ;
        }

      esp32s3_spi_set_regbits(SPI_CMD_REG(priv->config->id), SPI_USR_M);

      esp32s3_spi_sem_waitdone(priv);

      bytes -= n;
    }

  esp32s3_spi_clr_regbits(SPI_DMA_INT_ENA_REG(priv->config->id),
                          SPI_TRANS_DONE_INT_ENA_M);
