+static bool ag_lcd_read_ms(void *context, uint64_t *value)
+{
+  struct timespec now;
+
+  (void)context;
+  if (value == NULL || clock_gettime(CLOCK_MONOTONIC, &now) < 0 ||
+      now.tv_sec < 0)
+    {
+      return false;
+    }
+
+  *value = (uint64_t)now.tv_sec * 1000 + now.tv_nsec / 1000000;
+  return true;
+}
